import jwt from"jsonwebtoken";import bcrypt from"bcrypt";let SECRET_KEY=process.env.JWT_SECRET;function gerarToken(r){if(SECRET_KEY)return r={id:r.id,email:r.email},jwt.sign(r,SECRET_KEY,{expiresIn:"7d"});throw new Error("JWT_SECRET não configurado no ambiente")}function verificarToken(n,e,a){var r=n.headers.authorization,r=r&&r.split(" ")[1];if(!r)return e.status(401).json({erro:"Token não fornecido ou acesso negado."});jwt.verify(r,SECRET_KEY,(r,o)=>{if(r)return e.status(403).json({erro:"Token inválido ou expirado."});n.usuario=o,a()})}let saltRounds=10;async function criarHash(r){return bcrypt.hash(r,saltRounds)}async function compararSenha(r,o){return bcrypt.compare(r,o)}export{gerarToken,verificarToken,criarHash,compararSenha};